settings.custom_liquid:
{% comment %}
DAINTY HEART INITIAL NECKLACE
SINGLE / BUY 2 GET 1 FREE

Option 1: Initial (A-Z)
Option 2: Color (Gold / Silver)

Uses real Shopify Variant IDs.
Keeps original Add to Cart and Shop Pay buttons.

Requires Shopify automatic Buy X Get Y discount
for the 3-necklace bundle.
{% endcomment %}

{% if product != blank %}

{% assign bn_id = 'bn-' | append: section.id | append: '-' | append: block.id %}
{% assign bn_default = product.selected_or_first_available_variant %}

<style>

/* HIDE ORIGINAL VARIANT SELECTORS ONLY */

#shopify-section-{{ section.id }} variant-selects,
#shopify-section-{{ section.id }} variant-picker,
#shopify-section-{{ section.id }} .product-form__input--pills,
#shopify-section-{{ section.id }} .product-form__input--dropdown,
#shopify-section-{{ section.id }} .product-form__input--swatches {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  opacity: 0 !important;
  overflow: hidden !important;
  clip-path: inset(50%) !important;
  pointer-events: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* KEEP ORIGINAL ADD TO CART BUTTON */

/* HIDE PRODUCT-PAGE EXPRESS CHECKOUT
   ONLY WHEN BUY 2 GET 1 IS SELECTED */

#shopify-section-{{ section.id }}.bn-trio-mode
.shopify-payment-button,
#shopify-section-{{ section.id }}.bn-trio-mode
shopify-accelerated-checkout {
  display: none !important;
}

/* MAIN CONTAINER */

#{{ bn_id }} {
  --bn-border: #e7d9d1;
  --bn-accent: #a46f59;
  --bn-selected: #fff2eb;
  --bn-ink: #000000;

  width: 100%;
  max-width: 440px;
  margin: 18px 0 20px;
  color: #000000;
  font-family: inherit;
}

#{{ bn_id }} *,
#{{ bn_id }} *::before,
#{{ bn_id }} *::after {
  box-sizing: border-box;
}

/* STEP TITLES */

#{{ bn_id }} .bn-step {
  margin: 0 0 15px;
  color: #000000;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

/* PACKAGE GRID */

#{{ bn_id }} .bn-plans {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

#{{ bn_id }} button {
  font-family: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

/* PACKAGE CARDS */

#{{ bn_id }} .bn-plan {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;

  min-width: 0;
  min-height: 144px;

  padding: 21px 11px 13px;

  border: 1.5px solid var(--bn-border);
  border-radius: 13px;

  background: #ffffff;
  color: #000000;
  text-align: left;

  transition:
    background 0.2s,
    border-color 0.2s;
}

/* SELECTED PACKAGE */

#{{ bn_id }} .bn-plan.is-selected {
  border: 2px solid var(--bn-accent);
  background: var(--bn-selected);
}

/* PACKAGE BADGES */

#{{ bn_id }} .bn-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);

  background: #a46f59;
  color: #ffffff;

  padding: 4px 11px;
  border-radius: 20px;

  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

#{{ bn_id }} .bn-badge.gold {
  background: #b18732;
}

/* PACKAGE NAME */

#{{ bn_id }} .bn-name {
  color: #000000;
  font-size: 12px;
  font-weight: 850;
  line-height: 1.3;
}

/* PACKAGE PRICE */

#{{ bn_id }} .bn-price {
  display: block;
  margin: 7px 0 6px;

  color: #56392f;
  font-size: 26px;
  font-weight: 900;
  line-height: 1.2;
}

/* PACKAGE DESCRIPTION */

#{{ bn_id }} .bn-desc {
  display: block;
  color: #000000;

  font-size: 11px;
  font-weight: 600;
  line-height: 1.6;
}

/* FREE GIFT TEXT */

#{{ bn_id }} .bn-free {
  margin-top: 5px;
  color: #8c6338;
  font-size: 11px;
  font-weight: 850;
}

/* DIVIDER */

#{{ bn_id }} .bn-divider {
  border: 0;
  border-top: 1px solid var(--bn-border);
  margin: 22px 0 20px;
}

/* NECKLACE TABS */

#{{ bn_id }} .bn-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-bottom: 18px;
}

#{{ bn_id }} .bn-tabs[hidden] {
  display: none !important;
}

/* INDIVIDUAL NECKLACE TAB */

#{{ bn_id }} .bn-tab {
  min-width: 0;
  padding: 9px 4px;

  border: 1.5px solid var(--bn-border);
  border-radius: 8px;

  background: #ffffff;
  color: #000000;

  text-align: center;
  font-size: 11px;
  font-weight: 800;
}

/* ACTIVE NECKLACE TAB */

#{{ bn_id }} .bn-tab.is-selected {
  background: var(--bn-selected);
  border-color: var(--bn-accent);
}

#{{ bn_id }} .bn-tab small {
  display: block;
  margin-top: 3px;
  color: #000000;
  font-size: 10px;
  font-weight: 500;
}

/* OPTION LABELS */

#{{ bn_id }} .bn-label {
  color: #000000;
  font-size: 12px;
  font-weight: 800;
  margin: 0 0 9px;
}

/* LETTER GRID */

#{{ bn_id }} .bn-letters {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
  margin-bottom: 17px;
}

/* LETTER BUTTONS */

#{{ bn_id }} .bn-letter {
  width: 100%;
  min-width: 0;
  aspect-ratio: 1 / 1;

  border: 1.5px solid var(--bn-border);
  border-radius: 7px;

  background: #ffffff;
  color: #000000;

  font-size: 13px;
  font-weight: 800;
}

/* SELECTED LETTER */

#{{ bn_id }} .bn-letter.is-selected {
  border: 2px solid var(--bn-accent);
  background: var(--bn-selected);
}

/* COMPACT COLOR BUTTONS */

#{{ bn_id }} .bn-colors {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
}

#{{ bn_id }} .bn-color {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  padding: 8px 13px;

  border: 1.5px solid #d8c9c0;
  border-radius: 7px;

  background: #ffffff;
  color: #000000;

  font-size: 13px;
  font-weight: 750;
}

/* SELECTED COLOR */

#{{ bn_id }} .bn-color.is-selected {
  border: 2px solid var(--bn-accent);
  background: var(--bn-selected);
}

/* GOLD COLOR CIRCLE */

#{{ bn_id }} .bn-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid #0002;

  background: linear-gradient(
    135deg,
    #fff1ba,
    #c19044
  );
}

/* SILVER COLOR CIRCLE */

#{{ bn_id }} .bn-dot.silver {
  background: linear-gradient(
    135deg,
    #ffffff,
    #a4a8ae
  );
}

/* DISABLED OPTIONS */

#{{ bn_id }} button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

/* KEYBOARD ACCESSIBILITY */

#{{ bn_id }} button:focus-visible {
  outline: 3px solid #c7947b;
  outline-offset: 2px;
}

/* ERROR MESSAGE */

#{{ bn_id }} .bn-error {
  margin: 10px 0 0;
  color: #af3030;
  font-size: 12px;
  line-height: 1.5;
}

#{{ bn_id }} .bn-error:empty {
  display: none;
}

/* MOBILE */

@media screen and (max-width: 749px) {

  #{{ bn_id }} .bn-plan {
    padding: 20px 9px 12px;
    min-height: 142px;
  }

  #{{ bn_id }} .bn-price {
    font-size: 24px;
  }

  #{{ bn_id }} .bn-letters {
    gap: 6px;
  }

}

/* REDUCED MOTION */

@media (prefers-reduced-motion: reduce) {

  #{{ bn_id }} * {
    transition: none !important;
  }

}

</style>

<!-- MAIN BUNDLE SELECTOR -->

<div id="{{ bn_id }}" class="bn-picker">

  <!-- STEP 1 -->

  <p class="bn-step">
    STEP 1 — CHOOSE YOUR PACKAGE
  </p>

  <div
    class="bn-plans"
    role="group"
    aria-label="Choose your package"
  >

    <!-- SINGLE NECKLACE -->

    <button
      type="button"
      class="bn-plan is-selected"
      data-bn-plan="single"
      aria-pressed="true"
    >

      <span class="bn-badge">
        STANDARD
      </span>

      <span class="bn-name">
        SINGLE NECKLACE
      </span>

      <span
        class="bn-price"
        data-bn-single-price
      >
        {{ bn_default.price | money }}
      </span>

      <span class="bn-desc">
        ✓ 1 personalized necklace
      </span>

      <span class="bn-desc">
        ✓ Choose letter &amp; color
      </span>

    </button>

    <!-- BUY 2 GET 1 FREE -->

    <button
      type="button"
      class="bn-plan"
      data-bn-plan="trio"
      aria-pressed="false"
    >

      <span class="bn-badge gold">
        BEST VALUE ★
      </span>

      <span class="bn-name">
        BUY 2, GET 1 FREE
      </span>

      <span
        class="bn-price"
        data-bn-trio-price
      >
        {{ bn_default.price | times: 2 | money }}
      </span>

      <span class="bn-desc">
        ✓ 3 personalized necklaces
      </span>

      <span class="bn-desc">
        ✓ Choose each letter &amp; color
      </span>

      <span class="bn-free">
        🎁 1 necklace FREE
      </span>

    </button>

  </div>

  <!-- DIVIDER -->

  <hr class="bn-divider">

  <!-- STEP 2 -->

  <p class="bn-step">
    STEP 2 — CHOOSE YOUR INITIAL &amp; COLOR
  </p>

  <!-- THREE NECKLACE TABS -->

  <div
    class="bn-tabs"
    data-bn-tabs
    role="group"
    aria-label="Choose necklace to personalize"
    hidden
  >

    <button
      type="button"
      class="bn-tab is-selected"
      data-bn-slot="0"
    >
      NECKLACE 1
      <small></small>
    </button>

    <button
      type="button"
      class="bn-tab"
      data-bn-slot="1"
    >
      NECKLACE 2
      <small></small>
    </button>

    <button
      type="button"
      class="bn-tab"
      data-bn-slot="2"
    >
      FREE GIFT 🎁
      <small></small>
    </button>

  </div>

  <!-- CHOOSE INITIAL -->

  <p class="bn-label">
    Initial (A–Z)
  </p>

  <div
    class="bn-letters"
    data-bn-letters
    role="group"
    aria-label="Choose your initial"
  ></div>

  <!-- CHOOSE COLOR -->

  <p class="bn-label">
    Color
  </p>

  <div
    class="bn-colors"
    data-bn-colors
    role="group"
    aria-label="Choose your color"
  ></div>

  <!-- ERROR MESSAGE ONLY -->

  <p
    class="bn-error"
    data-bn-error
    role="alert"
    aria-live="polite"
  ></p>

  <!-- REAL SHOPIFY VARIANT IDS -->

  <script
    type="application/json"
    data-bn-variants
  >
    {{ product.variants | json }}
  </script>

</div>

<!-- JAVASCRIPT -->

<script>
(function () {

  'use strict';

  /* ROOT */

  const root = document.getElementById(
    {{ bn_id | json }}
  );

  if (!root || root.dataset.ready === 'true') {
    return;
  }

  root.dataset.ready = 'true';

  /* PRODUCT SECTION */

  const sectionRoot =
    document.getElementById(
      'shopify-section-{{ section.id }}'
    ) || document;

  /* REAL PRODUCT VARIANTS */

  const variants = JSON.parse(
    root.querySelector(
      '[data-bn-variants]'
    ).textContent
  );

  /* INITIAL VARIANT */

  const defaultVariantId =
    {{ bn_default.id | json }};

  const initialVariant =
    variants.find(v =>
      String(v.id) === String(defaultVariantId)
    ) ||
    variants.find(v => v.available) ||
    variants[0];

  if (!initialVariant) return;

  /* THREE NECKLACE SELECTIONS */

  const pieces = Array.from(
    { length: 3 },
    () => ({
      initial: initialVariant.option1,
      color: initialVariant.option2
    })
  );

  /* AVAILABLE INITIALS */

  const initials = [
    ...new Set(
      variants
        .map(v => v.option1)
        .filter(Boolean)
    )
  ].sort();

  /* AVAILABLE COLORS */

  const colors = [
    ...new Set(
      variants
        .map(v => v.option2)
        .filter(Boolean)
    )
  ].sort((a, b) => {

    if (/^gold$/i.test(a)) return -1;
    if (/^gold$/i.test(b)) return 1;

    return a.localeCompare(b);

  });

  /* STATE */

  let plan = 'single';
  let activePiece = 0;
  let adding = false;

  const lettersEl = root.querySelector(
    '[data-bn-letters]'
  );

  const colorsEl = root.querySelector(
    '[data-bn-colors]'
  );

  const errorEl = root.querySelector(
    '[data-bn-error]'
  );

  /* FIND EXACT VARIANT */

  function findVariant(piece) {

    return variants.find(v =>

      String(v.option1).toLowerCase() ===
      String(piece.initial).toLowerCase()

      &&

      String(v.option2).toLowerCase() ===
      String(piece.color).toLowerCase()

    );

  }

  /* FORMAT PRICE */

  function money(cents) {

    const currency =
      {{ cart.currency.iso_code | default: shop.currency | json }};

    try {

      return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: currency
      }).format(cents / 100);

    } catch (e) {

      return '$' + (cents / 100).toFixed(2);

    }

  }

  /* FIND ORIGINAL ADD TO CART FORM */

  function getProductForm() {

    return (

      sectionRoot.querySelector(
        'product-form form[action*="/cart/add"]'
      )

      ||

      sectionRoot.querySelector(
        'form[id^="product-form-"][action*="/cart/add"]'
      )

      ||

      sectionRoot.querySelector(
        'form[action*="/cart/add"]'
      )

    );

  }

  /* SYNC SINGLE VARIANT WITH SHOPIFY */

  function syncSingleVariant() {

    const variant = findVariant(pieces[0]);

    const form = getProductForm();

    if (!variant || !form) return;

    /* UPDATE VARIANT ID */

    const idInput = form.querySelector(
      '[name="id"]'
    );

    if (idInput) {

      if (
        String(idInput.value) !== String(variant.id)
      ) {

        idInput.value = String(variant.id);

        idInput.dispatchEvent(
          new Event('change', {
            bubbles: true
          })
        );

      }

      idInput.disabled = false;

    }

    /* SYNC NATIVE THEME PICKER */

    const picker = sectionRoot.querySelector(
      'variant-selects, variant-picker'
    );

    if (picker) {

      const values = [
        pieces[0].initial,
        pieces[0].color
      ];

      /* RADIO BUTTONS */

      const groups = picker.querySelectorAll(
        'fieldset'
      );

      groups.forEach((group, index) => {

        if (index > 1) return;

        const radio = Array.from(
          group.querySelectorAll(
            'input[type="radio"]'
          )
        ).find(el =>
          el.value === values[index]
        );

        if (radio) {
          radio.checked = true;
        }

      });

      /* DROPDOWN SELECTS */

      const selects = picker.querySelectorAll(
        'select'
      );

      selects.forEach((select, index) => {

        if (index > 1) return;

        const exists = Array.from(
          select.options
        ).some(option =>
          option.value === values[index]
        );

        if (exists) {
          select.value = values[index];
        }

      });

    }

    /* KEEP ADD TO CART BUTTON ENABLED */

    const addButton = form.querySelector(
      '[type="submit"][name="add"]'
    ) || form.querySelector(
      '[type="submit"]'
    );

    if (addButton) {

      addButton.disabled = !variant.available;

    }

    /* SINGLE QUANTITY */

    const quantity = form.querySelector(
      'input[name="quantity"]'
    );

    if (quantity) {
      quantity.value = 1;
    }

  }

  /* CREATE INITIAL BUTTONS */

  initials.forEach(letter => {

    const button = document.createElement(
      'button'
    );

    button.type = 'button';

    button.className = 'bn-letter';

    button.dataset.bnInitial = letter;

    button.textContent = letter;

    lettersEl.appendChild(button);

  });

  /* CREATE COLOR BUTTONS */

  colors.forEach(color => {

    const button = document.createElement(
      'button'
    );

    const swatch = document.createElement(
      'span'
    );

    const label = document.createElement(
      'span'
    );

    button.type = 'button';

    button.className = 'bn-color';

    button.dataset.bnColor = color;

    swatch.className = 'bn-dot';

    if (/silver/i.test(color)) {

      swatch.classList.add('silver');

    }

    swatch.setAttribute(
      'aria-hidden',
      'true'
    );

    label.textContent = color;

    button.appendChild(swatch);

    button.appendChild(label);

    colorsEl.appendChild(button);

  });

  /* UPDATE UI */

  function render() {

    const current = pieces[activePiece];

    /* SELECTED PACKAGE */

    root.querySelectorAll(
      '[data-bn-plan]'
    ).forEach(button => {

      const selected =
        button.dataset.bnPlan === plan;

      button.classList.toggle(
        'is-selected',
        selected
      );

      button.setAttribute(
        'aria-pressed',
        String(selected)
      );

    });

    /* SHOW 3 TABS ONLY FOR BUNDLE */

    root.querySelector(
      '[data-bn-tabs]'
    ).hidden = plan !== 'trio';

    /* UPDATE NECKLACE TABS */

    root.querySelectorAll(
      '[data-bn-slot]'
    ).forEach(button => {

      const index = Number(
        button.dataset.bnSlot
      );

      button.classList.toggle(
        'is-selected',
        index === activePiece
      );

      button.querySelector(
        'small'
      ).textContent =

        pieces[index].initial +
        ' · ' +
        pieces[index].color;

    });

    /* UPDATE INITIALS */

    lettersEl.querySelectorAll(
      'button'
    ).forEach(button => {

      const value =
        button.dataset.bnInitial;

      const variant = findVariant({
        initial: value,
        color: current.color
      });

      const selected =
        current.initial === value;

      button.classList.toggle(
        'is-selected',
        selected
      );

      button.setAttribute(
        'aria-pressed',
        String(selected)
      );

      button.disabled =
        !variant || !variant.available;

    });

    /* UPDATE COLORS */

    colorsEl.querySelectorAll(
      'button'
    ).forEach(button => {

      const value =
        button.dataset.bnColor;

      const variant = findVariant({
        initial: current.initial,
        color: value
      });

      const selected =
        current.color === value;

      button.classList.toggle(
        'is-selected',
        selected
      );

      button.setAttribute(
        'aria-pressed',
        String(selected)
      );

      button.disabled =
        !variant || !variant.available;

    });

    /* SINGLE PRICE */

    const single = findVariant(
      pieces[0]
    );

    root.querySelector(
      '[data-bn-single-price]'
    ).textContent = single

      ? money(single.price)

      : 'Unavailable';

    /* BUY 2 GET 1 FREE PRICE */

    const trio = pieces.map(
      findVariant
    );

    if (trio.every(Boolean)) {

      const subtotal = trio.reduce(
        (sum, variant) =>
          sum + variant.price,
        0
      );

      const freePrice = Math.min(
        ...trio.map(v => v.price)
      );

      root.querySelector(
        '[data-bn-trio-price]'
      ).textContent = money(
        subtotal - freePrice
      );

    } else {

      root.querySelector(
        '[data-bn-trio-price]'
      ).textContent = 'Unavailable';

    }

    /* EXPRESS CHECKOUT:
       VISIBLE FOR SINGLE,
       HIDDEN FOR 3-ITEM BUNDLE */

    sectionRoot.classList.toggle(
      'bn-trio-mode',
      plan === 'trio'
    );

    /* SYNC ORIGINAL PRODUCT FORM */

    if (plan === 'single' && !adding) {

      syncSingleVariant();

    }

  }

  /* HANDLE OPTION SELECTIONS */

  root.addEventListener(
    'click',
    function(event) {

      const button = event.target.closest(
        'button'
      );

      if (
        !button ||
        !root.contains(button) ||
        button.disabled
      ) {
        return;
      }

      errorEl.textContent = '';

      /* CHANGE PACKAGE */

      if (
        button.hasAttribute('data-bn-plan')
      ) {

        plan = button.dataset.bnPlan;

        activePiece = 0;

        render();

        return;

      }

      /* CHANGE ACTIVE NECKLACE */

      if (
        button.hasAttribute('data-bn-slot')
      ) {

        activePiece = Number(
          button.dataset.bnSlot
        );

        render();

        return;

      }

      /* CHANGE INITIAL */

      if (
        button.hasAttribute('data-bn-initial')
      ) {

        pieces[activePiece].initial =
          button.dataset.bnInitial;

        render();

        return;

      }

      /* CHANGE COLOR */

      if (
        button.hasAttribute('data-bn-color')
      ) {

        pieces[activePiece].color =
          button.dataset.bnColor;

        render();

      }

    }
  );

  /* ADD THREE NECKLACES */

  async function addBundle() {

    if (adding) return;

    /* GET EXACT VARIANT IDS */

    const selectedVariants = pieces.map(
      findVariant
    );

    if (
      selectedVariants.some(
        v => !v || !v.available
      )
    ) {

      errorEl.textContent =
        'One of your selections is unavailable.';

      return;

    }

    /* GROUP IDENTICAL VARIANTS */

    const grouped = new Map();

    selectedVariants.forEach(variant => {

      const id = String(variant.id);

      grouped.set(
        id,
        (grouped.get(id) || 0) + 1
      );

    });

    const items = [...grouped].map(
      ([id, quantity]) => ({
        id: Number(id),
        quantity: quantity
      })
    );

    /* ORIGINAL PRODUCT FORM */

    const form = getProductForm();

    const nativeButton = form

      ? form.querySelector(
          '[type="submit"][name="add"]'
        )

        ||

        form.querySelector(
          '[type="submit"]'
        )

      : null;

    adding = true;

    if (nativeButton) {

      nativeButton.disabled = true;

    }

    /* SHOPIFY CART API */

    try {

      const shopRoot =

        window.Shopify &&
        window.Shopify.routes &&
        window.Shopify.routes.root

          ? window.Shopify.routes.root

          : '/';

      const base = shopRoot.endsWith('/')

        ? shopRoot

        : shopRoot + '/';

      const response = await fetch(
        base + 'cart/add.js',
        {
          method: 'POST',

          credentials: 'same-origin',

          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          },

          body: JSON.stringify({
            items: items
          })
        }
      );

      const result = await response.json();

      if (!response.ok) {

        throw new Error(

          result.description ||

          result.message ||

          'Unable to add the bundle.'

        );

      }

      /* REDIRECT TO CART */

      window.location.assign(
        base + 'cart'
      );

    } catch (error) {

      errorEl.textContent =

        error.message ||

        'Something went wrong. Please try again.';

      adding = false;

      if (nativeButton) {

        nativeButton.disabled = false;

      }

    }

  }

  /* INTERCEPT ORIGINAL ADD TO CART
     ONLY FOR BUY 2 GET 1 FREE */

  document.addEventListener(
    'submit',

    function(event) {

      const form = getProductForm();

      if (
        !form ||
        event.target !== form
      ) {
        return;
      }

      /* SINGLE NECKLACE:
         USE NORMAL SHOPIFY CHECKOUT */

      if (plan === 'single') {

        syncSingleVariant();

        return;

      }

      /* THREE NECKLACES:
         ADD ALL 3 REAL VARIANT IDS */

      event.preventDefault();

      event.stopImmediatePropagation();

      if (!adding) {

        addBundle();

      }

    },

    true
  );

  /* INITIALIZE */

  render();

})();
</script>

