<script>
(function () {

  "use strict";

  /* FIND THIS GALLERY */

  var gallery = document.getElementById(
    {{ heart_gallery_id | json }}
  );

  if (!gallery) {
    return;
  }

  /* PREVENT DUPLICATE INITIALIZATION */

  if (gallery.dataset.galleryInitialized === "true") {
    return;
  }

  gallery.dataset.galleryInitialized = "true";

  /* ELEMENTS */

  var cards = Array.from(
    gallery.querySelectorAll(".heart-showcase-card")
  );

  var lightbox = gallery.querySelector(".heart-lightbox");

  var largeImage = gallery.querySelector(
    ".heart-lightbox-image"
  );

  var caption = gallery.querySelector(
    ".heart-lightbox-caption"
  );

  var counter = gallery.querySelector(
    ".heart-lightbox-counter"
  );

  var closeButton = gallery.querySelector(
    ".heart-lightbox-close"
  );

  var prevButton = gallery.querySelector(
    ".heart-lightbox-prev"
  );

  var nextButton = gallery.querySelector(
    ".heart-lightbox-next"
  );

  var currentIndex = 0;

  var lastFocused = null;

  /* COLLECT IMAGES */

  var images = cards.map(function (card) {

    var img = card.querySelector("img");

    var title = card.querySelector(
      ".heart-showcase-overlay h3"
    );

    return {

      src: img.getAttribute("src"),

      alt: img.getAttribute("alt") || "",

      title: title ? title.textContent.trim() : ""

    };

  });

  /* UPDATE ENLARGED IMAGE */

  function updateImage(index) {

    currentIndex = (
      index + images.length
    ) % images.length;

    var selected = images[currentIndex];

    largeImage.src = selected.src;

    largeImage.alt = selected.alt;

    caption.textContent = selected.title;

    counter.textContent =
      (currentIndex + 1) +
      " / " +
      images.length;

  }

  /* OPEN FULL SCREEN IMAGE */

  function openImage(index) {

    if (
      !images.length ||
      !lightbox ||
      typeof lightbox.showModal !== "function"
    ) {
      return;
    }

    lastFocused = document.activeElement;

    updateImage(index);

    if (!lightbox.open) {

      lightbox.showModal();

    }

    closeButton.focus();

  }

  /* CLOSE IMAGE VIEWER */

  function closeImage() {

    if (lightbox.open) {

      lightbox.close();

    }

    if (
      lastFocused &&
      typeof lastFocused.focus === "function"
    ) {

      lastFocused.focus();

    }

  }

  /* CLICK ON IMAGE */

  cards.forEach(function (card, index) {

    card.addEventListener("click", function () {

      openImage(index);

    });

  });

  /* CLOSE BUTTON */

  closeButton.addEventListener("click", function () {

    closeImage();

  });

  /* PREVIOUS BUTTON */

  prevButton.addEventListener("click", function () {

    updateImage(currentIndex - 1);

  });

  /* NEXT BUTTON */

  nextButton.addEventListener("click", function () {

    updateImage(currentIndex + 1);

  });

  /* CLICK ON DARK BACKGROUND TO CLOSE */

  lightbox.addEventListener("click", function (event) {

    if (event.target === lightbox) {

      closeImage();

    }

  });

  /* KEYBOARD NAVIGATION */

  lightbox.addEventListener("keydown", function (event) {

    if (event.key === "ArrowLeft") {

      event.preventDefault();

      updateImage(currentIndex - 1);

    }

    if (event.key === "ArrowRight") {

      event.preventDefault();

      updateImage(currentIndex + 1);

    }

    /* ESC works automatically on native dialog */

  });

  /* MOBILE SWIPE */

  var touchStartX = null;

  lightbox.addEventListener(
    "touchstart",
    function (event) {

      if (event.touches.length === 1) {

        touchStartX = event.touches[0].clientX;

      }

    },
    { passive: true }
  );

  lightbox.addEventListener(
    "touchend",
    function (event) {

      if (touchStartX === null) {
        return;
      }

      var endX = event.changedTouches[0].clientX;

      var diff = endX - touchStartX;

      if (Math.abs(diff) > 50) {

        if (diff < 0) {

          updateImage(currentIndex + 1);

        } else {

          updateImage(currentIndex - 1);

        }

      }

      touchStartX = null;

    },
    { passive: true }
  );

})();
</script>

