<script>
(function () {
  "use strict";

  var section = document.getElementById(
    {{ hg_id | json }}
  );

  if (!section || section.dataset.initialized === "true") {
    return;
  }

  section.dataset.initialized = "true";

  var button = section.querySelector(
    "[data-heart-guarantee-add]"
  );

  var status = section.querySelector(
    "[data-heart-guarantee-status]"
  );

  /*
   * Use the existing Shopify product form
   * to preserve the selected Initial, Color
   * and any bundle logic already configured.
   */

  button.addEventListener("click", function () {

    var forms = Array.from(
      document.querySelectorAll(
        'form[action*="/cart/add"]'
      )
    );

    var nativeButton = null;

    for (var i = 0; i < forms.length; i++) {

      var candidate = forms[i].querySelector(
        'button[name="add"],' +
        'button.product-form__submit,' +
        'button[type="submit"]:not([name="checkout"])'
      );

      if (candidate && !candidate.disabled) {
        nativeButton = candidate;
        break;
      }

    }

    if (nativeButton) {

      status.hidden = true;
      nativeButton.click();

      return;
    }

    /*
     * Fallback when no active product form
     * is available in the current theme.
     */

    var purchaseArea = document.querySelector(
      ".product-form, " +
      ".product__info-container, " +
      "product-info, " +
      '[id*="MainProduct"]'
    );

    if (purchaseArea) {

      purchaseArea.scrollIntoView({
        behavior: "smooth",
        block: "center"
      });

      status.textContent =
        "Please select your initial and color " +
        "using the product options above.";

      status.hidden = false;

      return;
    }

    status.textContent =
      "Please choose your necklace options " +
      "on the product page first.";

    status.hidden = false;

  });

})();
</script>
